INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', 'ミニトマトの芽吹き', '先週、庭の隅に置いていたプランターを覗くと、蒔いたばかりのミニトマトの芽がいくつも顔を出していた。正直、今回は手入れを怠っていたので、うまく育たないだろうと半ば諦めていた。（1）、芽はしっかりと土を割って伸びており、その生命力に驚かされた。

植物は人間の予想以上にたくましく、多少の不注意があっても環境さえ整っていれば自らの力で育っていくものらしい。（2）、私たちも完璧を求めすぎず、まずは種をまいてみることが大切なのかもしれない。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["だから","しかし","つまり","なぜなら"]', 1, '["「うまく育たないだろうと諦めていた」という予想に反して「芽がしっかり伸びていた」という結果が続くため、逆接の「しかし」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 71);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', 'ミニトマトの芽吹き', '先週、庭の隅に置いていたプランターを覗くと、蒔いたばかりのミニトマトの芽がいくつも顔を出していた。正直、今回は手入れを怠っていたので、うまく育たないだろうと半ば諦めていた。（1）、芽はしっかりと土を割って伸びており、その生命力に驚かされた。

植物は人間の予想以上にたくましく、多少の不注意があっても環境さえ整っていれば自らの力で育っていくものらしい。（2）、私たちも完璧を求めすぎず、まずは種をまいてみることが大切なのかもしれない。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だからこそ","ところが","たとえば","なぜなら"]', 0, '["「植物はたくましい」という前文の内容を踏まえて、「完璧を求めすぎず種をまいてみることが大切」という結論を導いているため、「だからこそ」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 71);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '大人になってから始めたピアノ', '子どもの頃に習っていたピアノを、三十歳を過ぎてから再び始めることにした。楽譜を読むのも指の動かし方も、すっかり忘れてしまっていて、最初の数週間は簡単な曲さえまともに弾けなかった。（1）、諦めずに毎日十分だけでも鍵盤に触れるようにしていたところ、少しずつ指が思うように動くようになってきた。

上達のスピードは子どもの頃よりもずっと遅い。（2）、大人になってから始めたからこそ味わえる達成感もあるのだと、今は感じている。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["それでも","つまり","なぜなら","ちなみに"]', 0, '["「まともに弾けなかった」という状況にもかかわらず「諦めずに続けた」という内容が続くため、逆接の「それでも」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 72);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '大人になってから始めたピアノ', '子どもの頃に習っていたピアノを、三十歳を過ぎてから再び始めることにした。楽譜を読むのも指の動かし方も、すっかり忘れてしまっていて、最初の数週間は簡単な曲さえまともに弾けなかった。（1）、諦めずに毎日十分だけでも鍵盤に触れるようにしていたところ、少しずつ指が思うように動くようになってきた。

上達のスピードは子どもの頃よりもずっと遅い。（2）、大人になってから始めたからこそ味わえる達成感もあるのだと、今は感じている。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だから","とはいえ","たとえば","つまり"]', 1, '["「上達が遅い」という否定的な内容の後に、「大人だからこそ味わえる達成感がある」という肯定的な内容を続けているため、「とはいえ」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 72);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '雨の日の図書館', '雨が降り続く休日、予定がすべて流れてしまったので、近所の図書館に足を運んでみることにした。傘を差して十分ほど歩く道のりは億劫に感じたが、（1）、館内に入ると静かで落ち着いた空気が広がっていて、来てよかったと思えた。

普段は忙しさにかまけて本を読む時間を作れずにいたが、こうして偶然できた時間を活用することで、思わぬ発見があるものだ。（2）、予定が崩れることも悪いことばかりではないのかもしれない。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["しかし","そのため","たとえば","つまり"]', 0, '["「歩くのが億劫だった」という気持ちと、「来てよかったと思えた」という結果が対比されているため、逆接の「しかし」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 73);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '雨の日の図書館', '雨が降り続く休日、予定がすべて流れてしまったので、近所の図書館に足を運んでみることにした。傘を差して十分ほど歩く道のりは億劫に感じたが、（1）、館内に入ると静かで落ち着いた空気が広がっていて、来てよかったと思えた。

普段は忙しさにかまけて本を読む時間を作れずにいたが、こうして偶然できた時間を活用することで、思わぬ発見があるものだ。（2）、予定が崩れることも悪いことばかりではないのかもしれない。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["そう考えると","ところが","なぜなら","たとえば"]', 0, '["前文の「思わぬ発見があるものだ」という内容を根拠として、「予定が崩れることも悪くない」という結論を導いているため、「そう考えると」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 73);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '早めの共有がもたらす効果', '入社したばかりの頃、資料作成に何時間もかけてしまい、先輩から「完璧を目指す前に、まず一度仕上げて見せてほしい」と言われたことがある。当時は納得できず、時間をかけるほど良いものができると思い込んでいた。（1）、実際に途中の段階で見せるようにしてみると、早い段階で軌道修正ができ、結果的に良い資料に仕上がることが増えた。

一人で抱え込みすぎず、早めに周囲と共有することには大きな意味がある。（2）、今では後輩にも同じアドバイスを伝えるようにしている。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["ところが","なぜなら","たとえば","すなわち"]', 0, '["「納得できなかった」という当初の考えに反して、実際に試してみると良い結果が得られたという展開のため、逆接の「ところが」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 74);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '早めの共有がもたらす効果', '入社したばかりの頃、資料作成に何時間もかけてしまい、先輩から「完璧を目指す前に、まず一度仕上げて見せてほしい」と言われたことがある。当時は納得できず、時間をかけるほど良いものができると思い込んでいた。（1）、実際に途中の段階で見せるようにしてみると、早い段階で軌道修正ができ、結果的に良い資料に仕上がることが増えた。

一人で抱え込みすぎず、早めに周囲と共有することには大きな意味がある。（2）、今では後輩にも同じアドバイスを伝えるようにしている。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["たとえば","そのため","しかし","ちなみに"]', 1, '["「早めに共有することには大きな意味がある」と考えるようになった結果として「後輩にもアドバイスを伝えている」という行動が続くため、順接の「そのため」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 74);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '犬との散歩道', '毎朝、愛犬と近所を散歩するのが日課になっている。長年通っている道なのに、季節ごとに違う草花が咲いているのに気づくと、新鮮な気持ちになる。（1）、同じ道でも歩くたびに違う表情を見せてくれるのだと感じている。

先日、いつも挨拶を交わしていた向かいの家の住人が引っ越してしまい、少し寂しさを覚えた。（2）、新しく越してきた家族とも、犬をきっかけに少しずつ言葉を交わすようになり、新たなつながりが生まれつつある。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["つまり","しかし","ところが","たとえば"]', 0, '["前文の内容(季節ごとに違う草花に気づく)を言い換えて「同じ道でも違う表情を見せてくれる」とまとめているため、「つまり」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 75);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '犬との散歩道', '毎朝、愛犬と近所を散歩するのが日課になっている。長年通っている道なのに、季節ごとに違う草花が咲いているのに気づくと、新鮮な気持ちになる。（1）、同じ道でも歩くたびに違う表情を見せてくれるのだと感じている。

先日、いつも挨拶を交わしていた向かいの家の住人が引っ越してしまい、少し寂しさを覚えた。（2）、新しく越してきた家族とも、犬をきっかけに少しずつ言葉を交わすようになり、新たなつながりが生まれつつある。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だから","しかし","つまり","なぜなら"]', 1, '["「寂しさを覚えた」という内容と、「新たなつながりが生まれつつある」という前向きな内容が対比されているため、逆接の「しかし」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め）', 75);
